insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Economy','External Sector & International Institutions','mcq','easy','Which one of the following was part of India''s trade policy reforms after 1991?','निम्नलिखित में से कौन-सा 1991 के बाद भारत के व्यापार नीति सुधारों का भाग था?','{"craft": "application"}'::jsonb,'[{"id": "a", "body": "Raising import tariffs to protect domestic industry from competition", "body_hi": "घरेलू उद्योग को प्रतिस्पर्धा से बचाने के लिए आयात शुल्क बढ़ाना", "isCorrect": false}, {"id": "b", "body": "Imposing new export duties to keep more goods in the home market", "body_hi": "घरेलू बाज़ार में अधिक वस्तुएँ रखने के लिए नए निर्यात शुल्क लगाना", "isCorrect": false}, {"id": "c", "body": "Extending import licensing to all consumer goods and farm products", "body_hi": "सभी उपभोक्ता वस्तुओं और कृषि उत्पादों पर आयात लाइसेंस लागू करना", "isCorrect": false}, {"id": "d", "body": "Dismantling quantitative restrictions on imports and exports", "body_hi": "आयात और निर्यात पर मात्रात्मक प्रतिबंधों को हटाना", "isCorrect": true}]'::jsonb,2,0.66,'The trade reforms aimed at dismantling quantitative restrictions on imports and exports, reducing tariff rates and removing licensing procedures for imports. Import licensing was abolished except for hazardous and environmentally sensitive industries, quantitative restrictions on imports of manufactured consumer goods and agricultural products were fully removed from April 2001, and export duties were removed to make Indian goods more competitive abroad. The other options describe the inward-looking policy that the reforms reversed.','व्यापार सुधारों का उद्देश्य आयात और निर्यात पर मात्रात्मक प्रतिबंध हटाना, प्रशुल्क दरें घटाना और आयात की लाइसेंस प्रक्रियाएँ समाप्त करना था। ख़तरनाक और पर्यावरण की दृष्टि से संवेदनशील उद्योगों को छोड़कर आयात लाइसेंस समाप्त कर दिया गया, विनिर्मित उपभोक्ता वस्तुओं और कृषि उत्पादों के आयात पर मात्रात्मक प्रतिबंध अप्रैल 2001 से पूरी तरह हटा दिए गए, और भारतीय वस्तुओं को विदेशों में अधिक प्रतिस्पर्धी बनाने के लिए निर्यात शुल्क हटाए गए। अन्य विकल्प उस अंतर्मुखी नीति का वर्णन करते हैं जिसे सुधारों ने पलटा।','l1-rev-1991-trade-reforms-qr','original_pattern_matched','NCERT Class XI, Economics -- Indian Economic Development, Chapter 3 (Liberalisation, Privatisation and Globalisation: An Appraisal).','draft'),
('upsc','Economy','External Sector & International Institutions','statement_based','medium','Consider the following statements about the Liberalised Exchange Rate Management System (LERMS):','उदारीकृत विनिमय दर प्रबंधन प्रणाली (LERMS) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Under LERMS, introduced in 1992, a part of foreign exchange earnings was converted at the official rate and the rest at the market rate.", "The dual rates were unified in 1993, moving the rupee to a market-determined exchange rate.", "Under the system, exporters had to surrender all their foreign exchange earnings at the official rate."], "statements_hi": ["1992 में लाई गई LERMS के अंतर्गत विदेशी मुद्रा आय का एक भाग आधिकारिक दर पर और शेष बाज़ार दर पर परिवर्तित होता था।", "1993 में दोनों दरें एकीकृत कर दी गईं, जिससे रुपया बाज़ार-निर्धारित विनिमय दर पर आ गया।", "इस प्रणाली में निर्यातकों को अपनी पूरी विदेशी मुद्रा आय आधिकारिक दर पर सौंपनी पड़ती थी।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. After the devaluation of July 1991, LERMS (March 1992) was a step from a fixed rate towards a market rate: 40 per cent of foreign exchange receipts were surrendered at the official rate, to meet the Government''s essential imports, and 60 per cent could be sold at the market rate. Statement 3 is wrong, since the larger share went at the market rate. In March 1993 the two rates were merged, and the rupee has since been market-determined, with the RBI intervening to smooth volatility.','कथन 1 और 2 सही हैं। जुलाई 1991 के अवमूल्यन के बाद LERMS (मार्च 1992) स्थिर दर से बाज़ार दर की ओर एक क़दम थी: सरकार के आवश्यक आयातों के लिए विदेशी मुद्रा प्राप्तियों का 40 प्रतिशत आधिकारिक दर पर सौंपा जाता था, और 60 प्रतिशत बाज़ार दर पर बेचा जा सकता था। कथन 3 गलत है, क्योंकि बड़ा हिस्सा बाज़ार दर पर जाता था। मार्च 1993 में दोनों दरें मिला दी गईं, और तब से रुपया बाज़ार-निर्धारित है, जिसमें RBI अस्थिरता घटाने के लिए हस्तक्षेप करता है।','l1-rev-lerms-1992','original_pattern_matched','Reserve Bank of India (exchange rate management since 1991; Report on Currency and Finance).','draft'),
('upsc','Economy','Agriculture & Food Economy','statement_based','easy','Consider the following statements about Kudumbashree:','कुडुंबश्री के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is a women-oriented, community-based poverty reduction programme of the Government of Kerala.", "It is run by NABARD in all States as a crop insurance scheme for women farmers."], "statements_hi": ["यह केरल सरकार का महिला-केंद्रित, समुदाय-आधारित निर्धनता उन्मूलन कार्यक्रम है।", "इसे नाबार्ड सभी राज्यों में महिला किसानों के लिए फ़सल बीमा योजना के रूप में चलाता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Kudumbashree began in 1995 with a thrift and credit society working as a small savings bank for poor women, to encourage them to save; these societies have been acclaimed as the largest informal banks in Asia in terms of participation and savings mobilised. Statement 2 is wrong: it is a programme of the Kerala Government, built on neighbourhood groups of women, not a NABARD crop-insurance scheme.','केवल कथन 1 सही है। कुडुंबश्री 1995 में एक बचत और ऋण समिति से आरंभ हुई, जो ग़रीब महिलाओं को बचत के लिए प्रेरित करने हेतु एक छोटे बचत बैंक की तरह काम करती थी; ये समितियाँ भागीदारी और जुटाई गई बचत के आधार पर एशिया के सबसे बड़े अनौपचारिक बैंकों के रूप में सराही गई हैं। कथन 2 गलत है: यह महिलाओं के पड़ोस-समूहों पर आधारित केरल सरकार का कार्यक्रम है, नाबार्ड की फ़सल बीमा योजना नहीं।','l1-rev-kudumbashree','original_pattern_matched','NCERT Class XI, Economics -- Indian Economic Development, Chapter 5 (Rural Development -- Rural Credit).','draft'),
('upsc','Economy','Agriculture & Food Economy','mcq','medium','Suppose the government fixes a support price for wheat above the price at which the market would clear. What is most likely to follow?','मान लीजिए सरकार गेहूँ का समर्थन मूल्य उस क़ीमत से ऊपर तय करती है जिस पर बाज़ार संतुलित होता। इसके बाद सबसे अधिक संभावना किसकी है?','{"craft": "application"}'::jsonb,'[{"id": "a", "body": "Demand will exceed supply, and wheat will have to be rationed through ration shops", "body_hi": "माँग पूर्ति से अधिक होगी, और गेहूँ को राशन दुकानों के माध्यम से राशन करना होगा", "isCorrect": false}, {"id": "b", "body": "The market price will fall below the support price, and farmers will gain from it", "body_hi": "बाज़ार क़ीमत समर्थन मूल्य से नीचे गिरेगी, और इससे किसानों को लाभ होगा", "isCorrect": false}, {"id": "c", "body": "Supply and demand will stay equal, as the support price only replaces the market price", "body_hi": "पूर्ति और माँग बराबर रहेंगी, क्योंकि समर्थन मूल्य केवल बाज़ार क़ीमत की जगह लेता है", "isCorrect": false}, {"id": "d", "body": "Supply will exceed demand, and the government must buy and store the surplus", "body_hi": "पूर्ति माँग से अधिक होगी, और सरकार को अधिशेष ख़रीदकर भंडारित करना होगा", "isCorrect": true}]'::jsonb,2,0.66,'A support price above the equilibrium is a price floor. At that price farmers offer more than buyers want to take, so there is excess supply; to keep the price from falling, the government must buy the surplus and store it, which is how procurement builds up buffer stocks. A price ceiling below the equilibrium does the opposite: it creates excess demand, which has to be met by rationing, as with goods sold through fair price shops. A minimum wage is another example of a price floor.','संतुलन से ऊपर समर्थन मूल्य एक न्यूनतम क़ीमत सीमा (price floor) है। उस क़ीमत पर किसान ख़रीदारों की इच्छा से अधिक बेचना चाहते हैं, इसलिए अधिपूर्ति होती है; क़ीमत गिरने से रोकने के लिए सरकार को अधिशेष ख़रीदकर भंडारित करना पड़ता है, और इसी तरह ख़रीद से बफ़र भंडार बनता है। संतुलन से नीचे अधिकतम क़ीमत सीमा (price ceiling) इसका उलटा करती है: वह अधिमाँग पैदा करती है, जिसे राशनिंग से पूरा करना पड़ता है, जैसे उचित मूल्य की दुकानों से बिकने वाली वस्तुओं में। न्यूनतम मज़दूरी भी न्यूनतम क़ीमत सीमा का एक उदाहरण है।','l1-rev-price-floor-support-price','original_pattern_matched','NCERT Class XII, Economics -- Introductory Microeconomics, Chapter 5 (Market Equilibrium -- price floor and price ceiling).','draft'),
('upsc','Economy','Agriculture & Food Economy','statement_based','medium','Consider the following statements about natural farming:','प्राकृतिक खेती के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It avoids chemical fertilisers and pesticides, relying on on-farm inputs such as cow dung and cow urine preparations (jeevamrit and beejamrit) and on mulching.", "The Union Cabinet approved a National Mission on Natural Farming in 2024.", "Under the Mission, Bio-input Resource Centres are to supply farmers with ready-to-use natural farming inputs.", "Andhra Pradesh has run a large community-managed natural farming programme."], "statements_hi": ["इसमें रासायनिक उर्वरकों और कीटनाशकों से बचा जाता है, और खेत पर बने आदानों -- जैसे गोबर और गोमूत्र से बने जीवामृत और बीजामृत -- तथा पलवार (mulching) पर निर्भर रहा जाता है।", "केंद्रीय मंत्रिमंडल ने 2024 में प्राकृतिक खेती पर राष्ट्रीय मिशन को स्वीकृति दी।", "मिशन के अंतर्गत जैव-आदान संसाधन केंद्र किसानों को उपयोग के लिए तैयार प्राकृतिक खेती आदान उपलब्ध कराएँगे।", "आंध्र प्रदेश ने समुदाय-प्रबंधित प्राकृतिक खेती का एक बड़ा कार्यक्रम चलाया है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. Natural farming aims to cut the cost of purchased inputs and restore soil health by using local, on-farm resources instead of chemicals. The National Mission on Natural Farming, a standalone centrally sponsored scheme of the Ministry of Agriculture and Farmers Welfare approved in November 2024, works through clusters of farmers, Bio-input Resource Centres and trained ''Krishi Sakhis''; Andhra Pradesh''s community-managed natural farming programme is among the largest such efforts.','चारों कथन सही हैं। प्राकृतिक खेती का उद्देश्य रसायनों के बजाय स्थानीय, खेत पर उपलब्ध संसाधनों के उपयोग से ख़रीदे गए आदानों की लागत घटाना और मिट्टी का स्वास्थ्य लौटाना है। नवंबर 2024 में स्वीकृत कृषि एवं किसान कल्याण मंत्रालय की स्वतंत्र केंद्र प्रायोजित योजना, प्राकृतिक खेती पर राष्ट्रीय मिशन, किसानों के समूहों, जैव-आदान संसाधन केंद्रों और प्रशिक्षित ''कृषि सखियों'' के माध्यम से काम करता है; आंध्र प्रदेश का समुदाय-प्रबंधित प्राकृतिक खेती कार्यक्रम ऐसे सबसे बड़े प्रयासों में से है।','l1-rev-natural-farming-mission','original_pattern_matched','Ministry of Agriculture and Farmers Welfare, National Mission on Natural Farming (Cabinet approval, November 2024).','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','easy','Consider the following statements about high-powered money (reserve money):','उच्च-शक्ति मुद्रा (high-powered money या आरक्षित मुद्रा) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It consists of the currency held by the public and the vault cash of banks, together with the deposits of the government and the commercial banks with the RBI.", "It is a liability of the commercial banks rather than of the Reserve Bank of India."], "statements_hi": ["इसमें जनता के पास की मुद्रा और बैंकों की तिजोरी नक़दी, तथा RBI के पास सरकार और वाणिज्यिक बैंकों की जमाएँ शामिल हैं।", "यह भारतीय रिज़र्व बैंक के बजाय वाणिज्यिक बैंकों की देनदारी है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. The total liability of the monetary authority -- the RBI -- is called the monetary base, reserve money or high-powered money. Statement 2 is wrong: it is the RBI''s liability. It is ''high-powered'' because the reserves banks hold with the RBI let them create deposits that are a multiple of those reserves, so a change in reserve money changes the money supply by more.','केवल कथन 1 सही है। मौद्रिक प्राधिकारी -- RBI -- की कुल देनदारी को मौद्रिक आधार, आरक्षित मुद्रा या उच्च-शक्ति मुद्रा कहते हैं। कथन 2 गलत है: यह RBI की देनदारी है। इसे ''उच्च-शक्ति'' इसलिए कहते हैं क्योंकि RBI के पास रखे बैंकों के आरक्षित कोष उन्हें इन कोषों के कई गुना जमाएँ बनाने देते हैं, इसलिए आरक्षित मुद्रा में परिवर्तन से मुद्रा पूर्ति में उससे अधिक परिवर्तन होता है।','l1-rev-high-powered-money','original_pattern_matched','NCERT Class XII, Economics -- Introductory Macroeconomics, Chapter 3 (Money and Banking).','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','medium','Consider the following statements about unclaimed bank deposits:','बैंकों की बिना दावे वाली (unclaimed) जमाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Deposits in accounts that have not been operated for ten years are transferred by banks to the RBI''s Depositor Education and Awareness (DEA) Fund.", "The RBI''s UDGAM portal lets people search for their unclaimed deposits across several banks at one place.", "Only deposits of more than one lakh rupees are transferred to the DEA Fund."], "statements_hi": ["जिन खातों में दस वर्ष से लेन-देन नहीं हुआ, उनकी जमाएँ बैंक RBI के जमाकर्ता शिक्षा और जागरूकता (DEA) कोष में हस्तांतरित करते हैं।", "RBI का उद्गम (UDGAM) पोर्टल लोगों को कई बैंकों में अपनी बिना दावे वाली जमाएँ एक ही जगह खोजने देता है।", "केवल एक लाख रुपये से अधिक की जमाएँ ही DEA कोष में हस्तांतरित होती हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Under Section 26A of the Banking Regulation Act, balances not claimed or operated for ten years, whatever their size, go to the DEA Fund, set up in 2014, which is used to promote depositors'' interests and awareness. The money is not lost: the depositor or the legal heir can still claim it from the bank, with interest where applicable, and the bank recovers it from the Fund. Statement 3 is therefore wrong, since there is no minimum amount.','कथन 1 और 2 सही हैं। बैंकिंग विनियमन अधिनियम की धारा 26A के अंतर्गत दस वर्ष तक बिना दावे या लेन-देन वाली राशियाँ, चाहे कितनी भी हों, 2014 में बने DEA कोष में जाती हैं, जिसका उपयोग जमाकर्ताओं के हितों और जागरूकता को बढ़ाने में होता है। धन खोता नहीं: जमाकर्ता या क़ानूनी वारिस अब भी बैंक से उसका दावा कर सकता है, जहाँ लागू हो वहाँ ब्याज सहित, और बैंक उसे कोष से वसूल लेता है। इसलिए कथन 3 गलत है, क्योंकि कोई न्यूनतम राशि नहीं है।','l1-rev-dea-fund-udgam','original_pattern_matched','Reserve Bank of India, Depositor Education and Awareness Fund Scheme (2014) and UDGAM portal (2023); Banking Regulation Act, 1949, Section 26A.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','easy','Consider the following statements about ASBA (Application Supported by Blocked Amount) in public issues of shares:','शेयरों के सार्वजनिक निर्गमों में ASBA (अवरुद्ध राशि द्वारा समर्थित आवेदन) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Under ASBA, the money for a share application stays in the investor''s bank account, blocked, until shares are allotted.", "If no shares are allotted, the investor has to apply to the company for a refund of the application money."], "statements_hi": ["ASBA में शेयर आवेदन की राशि निवेशक के बैंक खाते में ही, अवरुद्ध अवस्था में, शेयरों के आवंटन तक रहती है।", "यदि कोई शेयर आवंटित न हो, तो निवेशक को आवेदन राशि की वापसी के लिए कंपनी से अनुरोध करना पड़ता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. With ASBA, now required in public issues, the amount is only blocked in the investor''s account and keeps earning interest there; on allotment, just the amount for the shares actually allotted is debited. Statement 2 is wrong: if no shares, or fewer shares, are allotted, the rest of the blocked amount is simply released, so no refund has to be sought. Retail investors can also block the amount through a UPI mandate.','केवल कथन 1 सही है। ASBA में, जो अब सार्वजनिक निर्गमों में अनिवार्य है, राशि केवल निवेशक के खाते में अवरुद्ध रहती है और वहाँ ब्याज कमाती रहती है; आवंटन पर केवल वास्तव में आवंटित शेयरों की राशि ही काटी जाती है। कथन 2 गलत है: यदि कोई शेयर या कम शेयर आवंटित हों, तो अवरुद्ध राशि का शेष भाग बस मुक्त कर दिया जाता है, इसलिए वापसी माँगने की ज़रूरत नहीं होती। खुदरा निवेशक UPI अधिदेश (mandate) से भी राशि अवरुद्ध कर सकते हैं।','l1-rev-asba','original_pattern_matched','Securities and Exchange Board of India (ICDR Regulations and circulars on ASBA and the UPI mechanism).','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','mcq','medium','A company earns a return of 15 per cent on the capital it employs and can borrow at 10 per cent. Its owners decide to finance an expansion by borrowing rather than by issuing new shares, expecting a higher return on each equity share. This use of fixed-cost debt to raise the return to equity shareholders is called:','एक कंपनी अपनी लगाई पूँजी पर 15 प्रतिशत प्रतिफल कमाती है और 10 प्रतिशत पर उधार ले सकती है। उसके स्वामी नए शेयर जारी करने के बजाय उधार लेकर विस्तार का वित्तपोषण करने का निर्णय लेते हैं, इस आशा में कि हर समता शेयर पर प्रतिफल बढ़ेगा। समता अंशधारकों का प्रतिफल बढ़ाने के लिए स्थिर लागत वाले ऋण का यह उपयोग कहलाता है:','{"craft": "application"}'::jsonb,'[{"id": "a", "body": "ploughing back of profits", "body_hi": "लाभ का पुनर्निवेश", "isCorrect": false}, {"id": "b", "body": "a rights issue", "body_hi": "अधिकार निर्गम (rights issue)", "isCorrect": false}, {"id": "c", "body": "dematerialisation of shares", "body_hi": "शेयरों का अभौतिकीकरण", "isCorrect": false}, {"id": "d", "body": "trading on equity", "body_hi": "समता पर व्यापार (trading on equity)", "isCorrect": true}]'::jsonb,2,0.66,'Trading on equity is the increase in the profit of equity shareholders that comes from using funds with a fixed financial charge, such as interest on debt. Because the business earns 15 per cent on the borrowed money and pays only 10 per cent on it, the surplus goes to the shareholders and the earnings per share rise. It works only while the return on investment is higher than the rate of interest; if the return falls below that rate, the same debt lowers earnings per share, and more debt always means more financial risk. Ploughing back of profits is financing from retained earnings, a rights issue offers new shares to existing shareholders, and dematerialisation converts share certificates into electronic form.','समता पर व्यापार स्थिर वित्तीय भार वाले कोषों, जैसे ऋण पर ब्याज, के उपयोग से समता अंशधारकों के लाभ में होने वाली वृद्धि है। चूँकि व्यवसाय उधार के धन पर 15 प्रतिशत कमाता है और उस पर केवल 10 प्रतिशत चुकाता है, अधिशेष अंशधारकों को जाता है और प्रति शेयर आय बढ़ती है। यह तभी तक काम करता है जब तक निवेश पर प्रतिफल ब्याज दर से अधिक हो; प्रतिफल उस दर से नीचे जाने पर वही ऋण प्रति शेयर आय घटा देता है, और अधिक ऋण का अर्थ सदा अधिक वित्तीय जोखिम है। लाभ का पुनर्निवेश प्रतिधारित आय से वित्तपोषण है, अधिकार निर्गम मौजूदा अंशधारकों को नए शेयर देता है, और अभौतिकीकरण शेयर प्रमाणपत्रों को इलेक्ट्रॉनिक रूप में बदलता है।','l1-rev-trading-on-equity','original_pattern_matched','NCERT Class XII, Business Studies, Chapter 9 (Financial Management -- capital structure).','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about crowdfunding:','क्राउडफ़ंडिंग के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Crowdfunding raises small amounts of money from a large number of people, usually through online platforms.", "Donation-based crowdfunding, for medical treatment or social causes, is widely used in India.", "SEBI has framed regulations allowing unlisted companies to raise equity from the general public through online crowdfunding platforms."], "statements_hi": ["क्राउडफ़ंडिंग बड़ी संख्या में लोगों से, प्रायः ऑनलाइन मंचों के माध्यम से, छोटी-छोटी राशियाँ जुटाती है।", "चिकित्सा उपचार या सामाजिक कार्यों के लिए दान-आधारित क्राउडफ़ंडिंग भारत में व्यापक रूप से प्रयुक्त होती है।", "SEBI ने ऐसे विनियम बनाए हैं जो असूचीबद्ध कंपनियों को ऑनलाइन क्राउडफ़ंडिंग मंचों के माध्यम से आम जनता से इक्विटी जुटाने देते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Crowdfunding may be donation-based, reward-based, lending-based or equity-based. Statement 3 is wrong: SEBI floated a consultation paper on equity crowdfunding in 2014 but has not put such a framework in place, so an offer of shares to the public must follow the ordinary rules for public issues under the Companies Act and SEBI regulations; lending through peer-to-peer platforms is separately regulated by the RBI.','कथन 1 और 2 सही हैं। क्राउडफ़ंडिंग दान-आधारित, पुरस्कार-आधारित, ऋण-आधारित या इक्विटी-आधारित हो सकती है। कथन 3 गलत है: SEBI ने 2014 में इक्विटी क्राउडफ़ंडिंग पर एक परामर्श पत्र जारी किया, पर ऐसा कोई ढाँचा लागू नहीं किया, इसलिए जनता को शेयरों की पेशकश कंपनी अधिनियम और SEBI विनियमों के अंतर्गत सार्वजनिक निर्गमों के सामान्य नियमों के अनुसार ही हो सकती है; पीयर-टू-पीयर मंचों द्वारा उधार का विनियमन अलग से RBI करता है।','l1-rev-crowdfunding','original_pattern_matched','Securities and Exchange Board of India, Consultation Paper on Crowdfunding in India (2014).','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','medium','Consider the following statements about the platforms for listing small and medium enterprises (SMEs):','लघु और मध्यम उद्यमों (SMEs) की सूचीबद्धता के मंचों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["BSE and NSE run separate platforms, BSE SME and NSE Emerge, on which small and medium enterprises can list.", "Listing on these platforms has lighter eligibility requirements than the main board.", "SME public issues carry a large minimum application size, which keeps out investors who cannot bear high risk.", "A company listed on an SME platform can later migrate to the main board on meeting its criteria."], "statements_hi": ["BSE और NSE अलग मंच, BSE SME और NSE इमर्ज, चलाते हैं, जिन पर लघु और मध्यम उद्यम सूचीबद्ध हो सकते हैं।", "इन मंचों पर सूचीबद्धता की पात्रता शर्तें मुख्य बोर्ड से हल्की हैं।", "SME सार्वजनिक निर्गमों में न्यूनतम आवेदन राशि बड़ी होती है, जो अधिक जोखिम न उठा सकने वाले निवेशकों को दूर रखती है।", "SME मंच पर सूचीबद्ध कंपनी शर्तें पूरी करने पर बाद में मुख्य बोर्ड पर जा सकती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. The SME platforms, set up in 2012 under SEBI''s rules for SME issues, let smaller firms raise equity at lower cost; in return, the minimum application is kept large, trading is in large lots and market-making is required, so that the riskier shares reach investors able to judge and bear the risk. Once a company grows and meets the main board''s criteria, it can migrate there.','चारों कथन सही हैं। SEBI के SME निर्गम नियमों के अंतर्गत 2012 में बने SME मंच छोटी कंपनियों को कम लागत पर इक्विटी जुटाने देते हैं; बदले में न्यूनतम आवेदन बड़ा रखा जाता है, व्यापार बड़े लॉट में होता है और बाज़ार-निर्माण (market-making) आवश्यक है, ताकि अधिक जोखिम वाले शेयर उन निवेशकों तक पहुँचें जो जोखिम परख और उठा सकें। कंपनी बढ़कर मुख्य बोर्ड की शर्तें पूरी कर ले तो वहाँ जा सकती है।','l1-rev-sme-platforms','original_pattern_matched','Securities and Exchange Board of India, ICDR Regulations, Chapter IX (Initial public offer by small and medium enterprises); BSE SME and NSE Emerge.','draft'),
('upsc','Economy','Financial Markets, Instruments & Fintech','statement_based','hard','Consider the following statements about the Investor Education and Protection Fund (IEPF):','निवेशक शिक्षा और संरक्षण कोष (IEPF) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Dividends that remain unpaid or unclaimed for seven years are transferred to the Fund.", "Shares on which dividends have not been claimed for seven consecutive years are also transferred to the IEPF Authority.", "Investors can claim back such amounts and shares from the IEPF Authority.", "The Fund is administered by the Securities and Exchange Board of India."], "statements_hi": ["सात वर्ष तक अदत्त या बिना दावे वाले लाभांश इस कोष में हस्तांतरित होते हैं।", "जिन शेयरों पर लगातार सात वर्ष तक लाभांश का दावा नहीं किया गया, वे शेयर भी IEPF प्राधिकरण को हस्तांतरित होते हैं।", "निवेशक ऐसी राशियाँ और शेयर IEPF प्राधिकरण से वापस माँग सकते हैं।", "इस कोष का प्रशासन भारतीय प्रतिभूति और विनिमय बोर्ड करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1, 2 and 3 are correct. Under Sections 124 and 125 of the Companies Act, 2013, a company moves unclaimed dividends -- and, after seven straight years, the shares themselves -- to the Fund, which also receives matured deposits and debentures left unclaimed; the money is used to promote investor education and awareness, and the rightful owners can reclaim it through a set procedure. Statement 4 is wrong: the Fund is administered by the IEPF Authority under the Ministry of Corporate Affairs, not by SEBI.','कथन 1, 2 और 3 सही हैं। कंपनी अधिनियम, 2013 की धारा 124 और 125 के अंतर्गत कंपनी बिना दावे वाले लाभांश -- और लगातार सात वर्ष बाद स्वयं शेयर -- कोष में भेजती है, जिसमें बिना दावे की परिपक्व जमाएँ और डिबेंचर भी आते हैं; इस धन का उपयोग निवेशक शिक्षा और जागरूकता बढ़ाने में होता है, और वास्तविक स्वामी तय प्रक्रिया से इसे वापस पा सकते हैं। कथन 4 गलत है: कोष का प्रशासन कॉर्पोरेट कार्य मंत्रालय के अधीन IEPF प्राधिकरण करता है, SEBI नहीं।','l1-rev-iepf-unclaimed-dividends','original_pattern_matched','Companies Act, 2013 (Sections 124-125); Investor Education and Protection Fund Authority, Ministry of Corporate Affairs.','draft'),
('upsc','Economy','Industry, Infrastructure, Energy & Services','statement_based','easy','Consider the following statements about warehouses:','भांडागारों (warehouses) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Bonded warehouses hold imported goods until the customs duty on them is paid.", "Public warehouses can be used by the general public to store goods on payment of a charge."], "statements_hi": ["बंधित (bonded) भांडागार आयातित माल को तब तक रखते हैं जब तक उस पर सीमा शुल्क न चुका दिया जाए।", "सार्वजनिक भांडागारों का उपयोग आम जनता शुल्क देकर माल रखने के लिए कर सकती है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. Bonded warehouses, licensed by the government and usually near ports, let an importer pay the duty in instalments as the goods are taken out, and the goods can be packed, blended or graded while in bond. Public warehouses, licensed by the government, serve anyone for a fee; private warehouses are run by firms for their own goods, and government and cooperative warehouses are run by the Central and State Warehousing Corporations and by cooperatives.','दोनों कथन सही हैं। सरकार से अनुज्ञप्त और प्रायः बंदरगाहों के पास स्थित बंधित भांडागार आयातक को माल निकालते समय किस्तों में शुल्क चुकाने देते हैं, और बंध में रहते हुए माल की पैकिंग, मिश्रण या श्रेणीकरण हो सकता है। सरकार से अनुज्ञप्त सार्वजनिक भांडागार शुल्क लेकर किसी की भी सेवा करते हैं; निजी भांडागार फ़र्में अपने माल के लिए चलाती हैं, और सरकारी व सहकारी भांडागार केंद्रीय तथा राज्य भांडागार निगम और सहकारी समितियाँ चलाती हैं।','l1-rev-warehouse-types','original_pattern_matched','NCERT Class XI, Business Studies, Chapter 4 (Business Services -- Warehousing).','draft'),
('upsc','Economy','Industry, Infrastructure, Energy & Services','mcq','medium','On an online platform, individuals list their used bicycles, books and phones and sell them directly to other individuals. In the classification of e-business, this is:','एक ऑनलाइन मंच पर लोग अपनी पुरानी साइकिलें, किताबें और फ़ोन सूचीबद्ध करके उन्हें सीधे दूसरे लोगों को बेचते हैं। ई-व्यवसाय के वर्गीकरण में यह है:','{"craft": "application"}'::jsonb,'[{"id": "a", "body": "B2B commerce", "body_hi": "B2B (व्यवसाय से व्यवसाय) वाणिज्य", "isCorrect": false}, {"id": "b", "body": "B2C commerce", "body_hi": "B2C (व्यवसाय से उपभोक्ता) वाणिज्य", "isCorrect": false}, {"id": "c", "body": "intra-B commerce", "body_hi": "इंट्रा-B (व्यवसाय के भीतर) वाणिज्य", "isCorrect": false}, {"id": "d", "body": "C2C commerce", "body_hi": "C2C (उपभोक्ता से उपभोक्ता) वाणिज्य", "isCorrect": true}]'::jsonb,2,0.66,'In C2C (consumer-to-consumer) commerce, individuals trade with each other through an online platform, which matches buyers and sellers and often handles payment and feedback. B2B is trade between firms, such as a car maker ordering components from its suppliers; B2C is a firm selling to consumers, as in online shopping; and intra-B commerce links the departments of a single firm, such as production planning drawing on online sales data.','C2C (उपभोक्ता से उपभोक्ता) वाणिज्य में लोग एक ऑनलाइन मंच के माध्यम से आपस में व्यापार करते हैं, जो ख़रीदारों और विक्रेताओं को मिलाता है और प्रायः भुगतान व प्रतिक्रिया भी संभालता है। B2B फ़र्मों के बीच का व्यापार है, जैसे कोई कार निर्माता अपने आपूर्तिकर्ताओं से पुर्ज़े मँगाए; B2C में फ़र्म उपभोक्ताओं को बेचती है, जैसे ऑनलाइन ख़रीदारी में; और इंट्रा-B वाणिज्य एक ही फ़र्म के विभागों को जोड़ता है, जैसे ऑनलाइन बिक्री के आँकड़ों से उत्पादन की योजना बनाना।','l1-rev-e-business-c2c','original_pattern_matched','NCERT Class XI, Business Studies, Chapter 5 (Emerging Modes of Business -- e-business).','draft'),
('upsc','Economy','Industry, Infrastructure, Energy & Services','statement_based','medium','Consider the following statements about forms of business organisation:','व्यावसायिक संगठन के स्वरूपों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A sole proprietor''s liability is unlimited, so personal assets can be used to pay the debts of the business.", "In a Joint Hindu Family business, only the karta has unlimited liability; the liability of the other co-parceners is limited to their share in the family property.", "A cooperative society must be registered, which gives it a separate legal entity.", "A company has perpetual succession: its existence is not affected by the death or insolvency of its members."], "statements_hi": ["एकल स्वामी का दायित्व असीमित होता है, इसलिए व्यवसाय के ऋण चुकाने में उसकी निजी संपत्ति का उपयोग हो सकता है।", "संयुक्त हिंदू परिवार व्यवसाय में केवल कर्ता का दायित्व असीमित होता है; अन्य सहभागियों (co-parceners) का दायित्व पारिवारिक संपत्ति में उनके अंश तक सीमित होता है।", "सहकारी समिति का पंजीकरण अनिवार्य है, जिससे उसे पृथक वैधानिक अस्तित्व मिलता है।", "कंपनी का शाश्वत उत्तराधिकार होता है: उसके सदस्यों की मृत्यु या दिवालियापन से उसका अस्तित्व प्रभावित नहीं होता।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. Sole proprietorship and the Joint Hindu Family business are the oldest forms; the karta manages the family business and bears unlimited liability, while membership of the family is by birth. A cooperative''s registration gives it a separate legal identity, so it can enter contracts and hold property in its own name; a company, as an artificial person created by law, continues regardless of changes among its members, which is why it suits large, long-lived enterprises.','चारों कथन सही हैं। एकल स्वामित्व और संयुक्त हिंदू परिवार व्यवसाय सबसे पुराने स्वरूप हैं; कर्ता पारिवारिक व्यवसाय का प्रबंध करता है और असीमित दायित्व उठाता है, जबकि परिवार की सदस्यता जन्म से मिलती है। पंजीकरण से सहकारी समिति को पृथक वैधानिक पहचान मिलती है, इसलिए वह अपने नाम से अनुबंध कर सकती है और संपत्ति रख सकती है; क़ानून द्वारा बनाया गया कृत्रिम व्यक्ति होने के नाते कंपनी अपने सदस्यों में परिवर्तनों के बावजूद बनी रहती है, इसीलिए वह बड़े, दीर्घजीवी उद्यमों के लिए उपयुक्त है।','l1-rev-business-forms-liability','original_pattern_matched','NCERT Class XI, Business Studies, Chapter 2 (Forms of Business Organisation).','draft'),
('upsc','Economy','Industry, Infrastructure, Energy & Services','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "In the decades after 1950, the public sector was given the ''commanding heights'' of the Indian economy, especially in heavy and basic industries.", "assertion_hi": "1950 के बाद के दशकों में सार्वजनिक क्षेत्र को भारतीय अर्थव्यवस्था की ''शीर्ष स्थिति'' (commanding heights), विशेषकर भारी और आधारभूत उद्योगों में, सौंपी गई।", "reason": "Indian industrialists then lacked the capital and the large market needed for such investments, and the State wished to develop the economy along socialist lines.", "reason_hi": "तब भारतीय उद्योगपतियों के पास ऐसे निवेश के लिए आवश्यक पूँजी और बड़ा बाज़ार नहीं था, और राज्य अर्थव्यवस्था का विकास समाजवादी तर्ज़ पर करना चाहता था।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, and Statement-II explains Statement-I. At independence, Indian industrialists had neither the capital to undertake the large investments that industrial development required nor a market big enough to justify them; and the decision to develop the economy along socialist lines led to the policy of the State controlling the commanding heights. So the State took the lead in heavy and basic industries such as steel, machinery and power, while private industry was steered through licensing.','दोनों कथन सही हैं, और कथन-II कथन-I की व्याख्या करता है। स्वतंत्रता के समय भारतीय उद्योगपतियों के पास न तो औद्योगिक विकास के लिए आवश्यक बड़े निवेश करने की पूँजी थी और न ही उन्हें उचित ठहराने लायक़ बड़ा बाज़ार; और अर्थव्यवस्था को समाजवादी तर्ज़ पर विकसित करने के निर्णय से यह नीति बनी कि शीर्ष स्थितियाँ राज्य के नियंत्रण में रहें। इसलिए इस्पात, मशीनरी और बिजली जैसे भारी और आधारभूत उद्योगों में राज्य ने अगुवाई की, जबकि निजी उद्योग को लाइसेंस के ज़रिए दिशा दी गई।','l1-rev-commanding-heights','original_pattern_matched','NCERT Class XI, Economics -- Indian Economic Development, Chapter 2 (Indian Economy 1950-1990 -- Industry and Trade).','draft'),
('upsc','Economy','Macro Concepts, National Income & Inflation','assertion_reason','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "In an economy, realised (ex post) saving is always equal to realised (ex post) investment.", "assertion_hi": "किसी अर्थव्यवस्था में वास्तविक (यथार्थ या ex post) बचत सदा वास्तविक (ex post) निवेश के बराबर होती है।", "reason": "Any gap between planned saving and planned investment is made up by unplanned changes in firms'' inventories.", "reason_hi": "नियोजित बचत और नियोजित निवेश के बीच का कोई भी अंतर फ़र्मों के माल-भंडार (inventories) में अनियोजित परिवर्तनों से भर जाता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, and Statement-II explains Statement-I. Planned (ex ante) saving and investment are made by different people for different reasons and need not match. If households plan to save more than firms plan to invest, goods go unsold and pile up in inventories; since a change in inventories is counted as investment, the realised (ex post) investment rises to equal saving. Such unplanned changes prompt firms to change output, which moves the economy towards the level of income at which plans match.','दोनों कथन सही हैं, और कथन-II कथन-I की व्याख्या करता है। नियोजित (ex ante) बचत और निवेश अलग-अलग लोग अलग-अलग कारणों से करते हैं और उनका मेल खाना ज़रूरी नहीं। यदि परिवार फ़र्मों के नियोजित निवेश से अधिक बचत की योजना बनाएँ, तो माल बिना बिका रहकर भंडार में जमा होता है; चूँकि भंडार में परिवर्तन निवेश में गिना जाता है, वास्तविक (ex post) निवेश बढ़कर बचत के बराबर हो जाता है। ऐसे अनियोजित परिवर्तन फ़र्मों को उत्पादन बदलने के लिए प्रेरित करते हैं, जिससे अर्थव्यवस्था उस आय-स्तर की ओर बढ़ती है जिस पर योजनाएँ मेल खाती हैं।','l1-rev-ex-ante-ex-post','original_pattern_matched','NCERT Class XII, Economics -- Introductory Macroeconomics, Chapter 4 (Determination of Income and Employment).','draft'),
('upsc','Economy','Budget, Deficits & Public Debt','statement_based','medium','Consider the following statements about approaches to budgeting:','बजट बनाने के तरीक़ों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Participatory budgeting lets residents take part in deciding how a part of a local body''s budget is spent; Porto Alegre in Brazil is a well-known example.", "Green budgeting tracks how budget allocations affect the environment and climate goals.", "The Union Budget includes a statement of the allocations meant for the welfare of children.", "Gender budgeting means that half of every ministry''s allocation must be reserved for women."], "statements_hi": ["सहभागी बजट (participatory budgeting) निवासियों को यह तय करने में भाग लेने देता है कि स्थानीय निकाय के बजट का एक भाग कैसे ख़र्च हो; ब्राज़ील का पोर्टो अलेग्रे इसका प्रसिद्ध उदाहरण है।", "हरित बजट यह देखता है कि बजट आवंटन पर्यावरण और जलवायु लक्ष्यों को कैसे प्रभावित करते हैं।", "केंद्रीय बजट में बच्चों के कल्याण के लिए आवंटनों का एक विवरण शामिल होता है।", "जेंडर बजट का अर्थ है कि हर मंत्रालय के आवंटन का आधा भाग महिलाओं के लिए आरक्षित हो।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1, 2 and 3 are correct. Each of these is a way of looking at the same budget through a particular lens -- who decides, what it does to the environment, how much reaches children. Indian cities such as Pune have tried participatory budgeting, and some States tag their allocations for climate. Statement 4 is wrong: gender budgeting reports how much of the budget is meant for women -- schemes wholly for women and schemes in which at least 30 per cent of the allocation is for them -- so that policy can be judged by its effect on women; it sets no fixed share.','कथन 1, 2 और 3 सही हैं। इनमें से हर एक उसी बजट को एक विशेष दृष्टि से देखने का तरीक़ा है -- निर्णय कौन करता है, पर्यावरण पर उसका क्या असर है, बच्चों तक कितना पहुँचता है। पुणे जैसे भारतीय नगरों ने सहभागी बजट आज़माया है, और कुछ राज्य अपने आवंटनों को जलवायु के लिए चिह्नित करते हैं। कथन 4 गलत है: जेंडर बजट यह दिखाता है कि बजट का कितना भाग महिलाओं के लिए है -- पूरी तरह महिलाओं की योजनाएँ और वे योजनाएँ जिनके आवंटन का कम से कम 30 प्रतिशत उनके लिए है -- ताकि नीति को महिलाओं पर उसके प्रभाव से परखा जा सके; यह कोई निश्चित हिस्सा तय नहीं करता।','l1-rev-budgeting-approaches','original_pattern_matched','Ministry of Finance, Union Budget (Expenditure Profile -- Statement on Allocations for the Welfare of Children; Gender Budget Statement).','draft'),
('upsc','Economy','Taxation & Fiscal Federalism','assertion_reason','hard','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Indirect taxes on items of mass consumption tend to be regressive.", "assertion_hi": "जन-उपभोग की वस्तुओं पर अप्रत्यक्ष कर प्रतिगामी (regressive) होते हैं।", "reason": "The poor spend a larger share of their income on consumption than the rich, so such taxes take a larger share of their income.", "reason_hi": "ग़रीब अपनी आय का अमीरों से बड़ा हिस्सा उपभोग पर ख़र्च करते हैं, इसलिए ऐसे कर उनकी आय का बड़ा हिस्सा ले लेते हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "craft": "inference"}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, and Statement-II explains Statement-I. A tax is regressive when it takes a smaller share of income as income rises. An indirect tax on a good is the same for every buyer, but a poor household spends almost all its income on consumption while a rich one saves a good part of it, so the tax is a heavier burden on the poor. This is why basic necessities are taxed lightly or exempted, higher rates are kept for luxuries, and progressive direct taxes such as income tax are used to redistribute income.','दोनों कथन सही हैं, और कथन-II कथन-I की व्याख्या करता है। कोई कर प्रतिगामी तब है जब आय बढ़ने पर वह आय का छोटा हिस्सा लेता है। किसी वस्तु पर अप्रत्यक्ष कर हर ख़रीदार के लिए समान होता है, पर ग़रीब परिवार लगभग पूरी आय उपभोग पर ख़र्च करता है जबकि अमीर परिवार उसका अच्छा-ख़ासा भाग बचाता है, इसलिए यह कर ग़रीबों पर भारी पड़ता है। इसीलिए बुनियादी ज़रूरतों पर कम कर लगता है या छूट मिलती है, विलासिता की वस्तुओं के लिए ऊँची दरें रखी जाती हैं, और आय के पुनर्वितरण के लिए आयकर जैसे प्रगतिशील प्रत्यक्ष करों का उपयोग होता है।','l1-rev-regressive-indirect-taxes','original_pattern_matched','NCERT Class XII, Economics -- Introductory Macroeconomics, Chapter 5 (Government Budget and the Economy -- the redistribution function).','draft'),
('upsc','Economy','Inclusive Growth, Welfare & Demography','match_the_following','hard','Consider the following pairs relating to China''s development path:','चीन के विकास पथ से संबंधित निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Great Leap Forward", "2. One-child norm", "3. Great Proletarian Cultural Revolution", "4. Economic reforms in China"], "list_1_hi": ["1. ग्रेट लीप फ़ॉरवर्ड", "2. एक-संतान मानदंड", "3. महान सर्वहारा सांस्कृतिक क्रांति", "4. चीन में आर्थिक सुधार"], "list_2": ["A campaign begun in 1958 to industrialise the country on a massive scale", "Introduced in China in the late 1970s", "1966-76, when students and professionals were sent to work and learn in the countryside", "Began in 1991, at the same time as India''s"], "list_2_hi": ["देश का बड़े पैमाने पर औद्योगीकरण करने के लिए 1958 में आरंभ अभियान", "चीन में 1970 के दशक के अंत में लागू", "1966-76, जब विद्यार्थियों और पेशेवरों को ग्रामीण क्षेत्रों में काम करने और सीखने भेजा गया", "1991 में, भारत के साथ ही, आरंभ हुए"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Pairs 1, 2 and 3 are correctly matched. Under the Great Leap Forward people were encouraged to set up industries in their backyards, and in rural areas communes were started, under which people cultivated land collectively. The one-child norm slowed population growth but led to a fall in the sex ratio and, in time, an ageing population. Pair 4 is wrong: China began its reforms in phases from 1978, well before India''s reforms of 1991 -- which is one reason its growth, industrialisation and poverty reduction moved ahead of India''s.','युग्म 1, 2 और 3 सही सुमेलित हैं। ग्रेट लीप फ़ॉरवर्ड में लोगों को अपने घर-आँगन में उद्योग लगाने के लिए प्रोत्साहित किया गया, और ग्रामीण क्षेत्रों में कम्यून आरंभ हुए, जिनमें लोग सामूहिक रूप से खेती करते थे। एक-संतान मानदंड ने जनसंख्या वृद्धि धीमी की, पर इससे लिंगानुपात गिरा और समय के साथ आबादी बूढ़ी होने लगी। युग्म 4 गलत है: चीन ने 1978 से चरणों में सुधार आरंभ किए, भारत के 1991 के सुधारों से काफ़ी पहले -- यह एक कारण है कि उसकी वृद्धि, औद्योगीकरण और निर्धनता में कमी भारत से आगे निकल गए।','l1-rev-china-development-pairs','original_pattern_matched','NCERT Class XI, Economics -- Indian Economic Development (Comparative Development Experiences of India and its Neighbours).','draft')
